luate(p,b,bound).Accepted,"neutral capacity not inferred from phase");bound.Rating.NeutralRatedA=400;rq.NeutralRmsA=500;Check(BusbarSelection.Evaluate(p,b,bound).Failed,"neutral capacity independent corrected");rq.NeutralRmsA=300;Check(BusbarSelection.Evaluate(p,b,bound).Accepted,"synthetic independent N rating valid");bound.Rating.HasNeutral=false;bound.Rating.NeutralRatedA=null;rq.RequiresNeutral=false;rq.NeutralRmsA=0;rq.MountingVerified=null;Check(!BusbarSelection.Evaluate(p,b,bound).Accepted,"mounting unknown no pass");rq.MountingVerified=true;rq.CapacityFactor=null;Check(!BusbarSelection.Evaluate(p,b,bound).Accepted,"unknown corrections not1");rq.CapacityFactor=.97;rq.CurrentEvidence=BoardCurrentEvidence.FlowSinusoidal;Check(!BusbarSelection.Evaluate(p,b,bound).Accepted,"fundamental not assumedRMS");rq.SinusoidalReference="Caso QA senoidal sem harmônicas";Check(!BusbarSelection.Evaluate(p,b,bound).Accepted,"flow without valid model pending");rq.CurrentEvidence=BoardCurrentEvidence.ExternalRms;rq.SinusoidalReference="";rq.RequiredRmsUpperKA=0;Check(!BusbarSelection.Evaluate(p,b,bound).Accepted,"zero unknown fault not pass");rq.RequiredRmsUpperKA=35;bound.Engine="future";Reject(p.Validate,"unknown revision");bound.Engine=BusbarSelection.EngineId;rq.CapacityFactor=1.1;Reject(p.Validate,"factor cannot uprate nominal");rq.CapacityFactor=.97;string csv=Path.Combine(dir,"roundtrip.csv");BusbarSelection.Export(rows,csv);BusbarSelection.Export(rows,csv);Check(BusbarSelection.Import(csv).Count==6&&File.Exists(csv+".bak"),"catalog roundtrip and backup");var copy=bound.Copy();copy.Rating.RatedCurrentA=1;copy.Requirements.L1RmsA=1;Check(bound.Rating.RatedCurrentA==1000&&bound.Requirements.L1RmsA==850,"deep binding copy");Check(File.ReadAllText(project).Contains("busbar-assembly-v1"),"capability persisted");string memory=EngineeringReport.Memory(p,Engineering.Analyze(p));Check(memory.Contains("CONJUNTO DE BARRAS/BUSWAY")&&memory.Contains("Maior fase, não média"),"board rating in memory");Check(memory==EngineeringReport.Memory(restored,Engineering.Analyze(restored)),"snapshot memory exact after reopen");var selected=EngineeringReport.Memory(p,Engineering.Analyze(p),new System.Collections.Generic.HashSet<string>(new[]{b.Circuits[1].Id}));Check(selected.Contains("CONJUNTO DE BARRAS/BUSWAY"),"selected circuit includes complete board rating");var noSelected=EngineeringReport.Memory(p,Engineering.Analyze(p),new System.Collections.Generic.HashSet<string>());Check(!noSelected.Contains("CONJUNTO DE BARRAS/BUSWAY"),"empty selection omits board details");var flowProject=Project.Load(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"referencias-fluxo/mixed-three-level.circuito"));var remote=flowProject.Boards[2];var flowRequirements=Requirements();flowRequirements.CurrentEvidence=BoardCurrentEvidence.FlowSinusoidal;flowRequirements.RequiresNeutral=true;flowRequirements.SinusoidalReference="Caso sintético fundamental sem harmônicas, todas as cargasPQ/Z senoidais";var synthetic=rows.First(x=>x.RatedCurrentA==1000&&x.FrequencyHz==60).Copy();synthetic.Reference="Conjunto N sintéticoQA";synthetic.Source="QA independente do catálogoOEM";synthetic.HasNeutral=true;synthetic.NeutralRatedA=1000;var flowBinding=BusbarSelection.Bind(flowProject,remote,synthetic,flowRequirements);var evaluatedFlow=BusbarSelection.Evaluate(flowProject,remote,flowBinding);Check(evaluatedFlow.Accepted,evaluatedFlow.Detail);var feeder=flowProject.Boards[1].Circuits.First(x=>x.ChildBoardId==remote.Id);var currentFlow=NetworkFlow.Run(flowProject).For(feeder);Near(evaluatedFlow.PhaseRmsA.Max(),currentFlow.MaximumPhaseCurrentA,"sum actual phasors per board then maxphase");Near(evaluatedFlow.NeutralRmsA.Value,currentFlow.NeutralCurrentA,"board N from actual phasor sum");flowBinding.Requirements.SinusoidalReference="";Check(!BusbarSelection.Evaluate(flowProject,remote,flowBinding).Accepted,"fundamental N no automatic RMS proof");flowBinding.Requirements.SinusoidalReference=flowRequirements.SinusoidalReference;flowProject.FlowSettings.Relaxation=.6;Check(!BusbarSelection.Evaluate(flowProject,remote,flowBinding).Accepted,"flow profile changes invalidate evidence binding");var understate=flowRequirements.Copy();understate.CurrentEvidence=BoardCurrentEvidence.ExternalRms;understate.L1RmsA=understate.L2RmsA=understate.L3RmsA=.1;understate.NeutralRmsA=0;Check(BusbarSelection.Evaluate(flowProject,remote,BusbarSelection.Bind(flowProject,remote,synthetic,understate)).Failed,"externalRMS cannot understate modeled fundamental");var extremeProject=Project.Load(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"referencias-extremos/remote-source-three-level.circuito"));var root=extremeProject.Boards[0];var limited=Requirements();limited.RequiredRmsUpperKA=.5;var extremeCandidate=BusbarSelection.ReferenceCatalog().First(x=>x.RatedCurrentA==1000&&x.FrequencyHz==60);Check(BusbarSelection.Evaluate(extremeProject,root,BusbarSelection.Bind(extremeProject,root,extremeCandidate,limited)).Failed,"external envelope cannot understateF23 initial maximum");extremeProject.FaultExtremes.BoundsReference="";Check(!BusbarSelection.Evaluate(extremeProject,root,BusbarSelection.Bind(extremeProject,root,extremeCandidate,limited)).Accepted,"incomplete existingF23 remains pending");var previous=Environment.GetEnvironmentVariable("CIRCUITO_QA_PREVIOUS_EXE");if(!String.IsNullOrEmpty(previous)){var asm=Assembly.LoadFile(Path.GetFullPath(previous));bool refused=false;try{asm.GetType("CircuitoStudio.Project").GetMethod("Load").Invoke(null,new object[]{project});}catch(TargetInvocationException e){refused=e.InnerException is InvalidDataException;}Check(refused,"actual previous37 reader refuses new capability");}using(var form=new BusbarSelectionForm(p,b)){var originalBinding=b.BusbarSelection;form.SelectRating(originalBinding.Rating.Reference);Check(!form.Changed&&form.EvaluateDraft(false).Accepted&&Object.ReferenceEquals(b.BusbarSelection,originalBinding),"form evaluate copy");Check(form.Recommend().RatedCurrentA==1000&&Object.ReferenceEquals(b.BusbarSelection,originalBinding),"form recommendation no mutation");form.EvaluateDraft(true);Check(form.Changed&&b.BusbarSelection!=originalBinding&&b.BusbarSelection.Requirements!=originalBinding.Requirements,"form commits independent snapshot");if(Environment.GetEnvironmentVariable("CIRCUITO_QA_VISUAL")=="1"){form.StartPosition=FormStartPosition.Manual;form.Location=new Point(5,5);form.Show();Application.DoEvents();form.Refresh();form.Update();Action<string> capture=name=>{Application.DoEvents();form.Refresh();form.Update();using(var bmp=new Bitmap(form.ClientSize.Width,form.ClientSize.Height)){using(var g=Graphics.FromImage(bmp))g.CopyFromScreen(form.PointToScreen(Point.Empty),Point.Empty,form.ClientSize);bmp.Save(Path.Combine(dir,name+".png"));}};capture("barras-exigencias");var split=form.Controls.OfType<SplitContainer>().First();split.Panel1.Controls.OfType<TabControl>().First().SelectedIndex=1;Check(form.EvaluateDraft(false).Accepted,"catalog tab preserves explicit choice");capture("barras-catalogo");form.Hide();}}Console.WriteLine("PASS: "+n+" busbar assertions");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
